      "Kurz ziehen lassen und in einer Pfanne mit der angedrückten Knoblauchzehe und etwas Öl bei mittlerer Hitze rundherum anbraten.",
      "Er darf dabei auch ruhig Farbe nehmen.Den Tafelspitz in einen backofentauglichen Schmortopf mit Deckel geben. In der Pfanne nun die Zwiebel, die Karotte und den Sellerie anschwitzen, das Tomatenmark dazugeben und kurz mitbraten, mit dem Rotwein ablöschen und einköcheln lassen.",
      "Mit der Geflügelbrühe auffüllen, durchrühren und zum Fleisch geben. Deckel drauf und für drei bis vier Stunden in den Backofen, zwischendurch das Fleisch einmal wenden und ggf. noch etwas Brühe nachgießen.Frühzeitig aus der Butter und dem Mehl eine dunkle Mehlschwitze herstellen und erkalten (!) lassen.Nach der Garzeit das Fleisch aus dem Schmorsud nehmen und im abgeschalteten Backofen ruhen lassen.",
