      "Mit dem verbliebenen Senf, Salz und Pfeffer bei Bedarf noch abschmecken.Das (butterweiche) Fleisch vorsichtig mit einem sehr scharfem Messer oder auch einem Elektromesser quer zur Faser in dünne Scheiben schneiden und mit der Soße anrichten.Dazu serviere ich die herzhaften Hefeknödel (aus der DB) und einen gemischten Salat."
